{"code":"import pandas as pd, statsmodels.formula.api as smf
x=pd.read_csv('data/explore.csv')
cols=['anneal_temp','cool_rate','carbon_pct','chromium_pct','grain_size','humidity','press_time','nickel_pct','porosity','cure_hours']
for c in cols:
 d=x[['tensile_mpa','lab',c]].dropna(); m=smf.ols(f'tensile_mpa ~ Q("{c}") + C(lab)',d).fit(); print(c, len(d), round(m.params.iloc[1],4),round(m.pvalues.iloc[1],6), round(d[[c,'tensile_mpa']].corr().iloc[0,1],3))"}

{"code":"import pandas as pd, statsmodels.formula.api as smf
x=pd.read_csv('data/explore.csv'); cols=['anneal_temp','cool_rate','carbon_pct','chromium_pct','grain_size','humidity','press_time','nickel_pct','porosity','cure_hours']
# residualized outcomes by lab; inspect exposure relationships with lab and outcome residual
for c in cols:
 d=x[['tensile_mpa','lab',c]].dropna(); m=smf.ols(f'tensile_mpa ~ C(lab)+Q("{c}")',d).fit(); print(c,round(m.params.iloc[-1],3),round(m.tvalues.iloc[-1],2), 'within var',round(d.groupby('lab')[c].mean().std(),2))"}

